   347  void fxGetNextNumber(txParser* parser, txNumber theNumber)
   348  {
   349          parser->number2 = theNumber;
   350          parser->integer2 = (txInteger)parser->number2;
   351          theNumber = parser->integer2;
   352          if (parser->number2 == theNumber)
   353                  parser->token2 = XS_TOKEN_INTEGER;
